"""Pinned, source-backed corrections for legacy postseason snapshots.

The provider's seasonType was absent from the preserved schema-3 snapshots, so
this registry binds each correction to exact legacy identity and derives the
canonical week from :mod:`cfb.week_calendar`.  The payload is code-owned: a
manifest or caller cannot make an arbitrary self-sealed registry authoritative.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime
import hashlib
import json
import re
from collections.abc import Mapping, Sequence
from typing import Any, Final
from zoneinfo import ZoneInfo

from .week_calendar import canonical_postseason_week

REGISTRY_VERSION: Final[str] = "postseason-recovery-v2"
REGISTRY_POLICY_ID: Final[str] = "cfb-postseason-registry-v2"
PINNED_SOURCE_EVIDENCE_SHA256: Final[str] = "170a7bc497cc5fb05f79d0982ca712d8d1ea5d0ff6afcea97dc3294dc292125e"
PINNED_OFFICIAL_SOURCES: Final[dict[str, str]] = {'ncaa_2024_postseason_scoreboard': 'https://www.ncaa.com/scoreboard/football/fbs/2024/P/all-conf', 'ncaa_2025_postseason_scoreboard': 'https://www.ncaa.com/scoreboard/football/fbs/2025/P/all-conf', 'cfp_2024_25_schedule': 'https://collegefootballplayoff.com/sports/football/schedule/2024-25', 'cfp_2025_26_schedule': 'https://collegefootballplayoff.com/sports/football/schedule/2025-26', 'cfp_2024_25_dates_release': 'https://collegefootballplayoff.com/news/2023/5/2/24-25-dates'}
PINNED_SNAPSHOT_CHECKSUMS: Final[dict[int, str]] = {2024: '35b3783a78ca6fa64905a802be51e82b0b5006fae17ee475bd3cd3c45a3905a1', 2025: '7663694144e27034bab79a4db4a7a37ce27d0f0dede34704654cd74d02171853', 2026: 'ae033bc7cb24cc3202791fb21b1d0bee2d2976d88b9e10c9d986513c03fe6f3d'}


@dataclass(frozen=True)
class PostseasonCorrection:
    """One exact legacy game binding and its independently derived target."""

    provider_id: str
    season: int
    snapshot_date: str
    home_team: str
    away_team: str
    notes: str | None
    provider_week: int
    original_canonical_week: int
    canonical_week: int
    source_snapshot_checksum: str
    phase: str = "postseason"
    phase_source: str = "recovery_registry"
    provider_phase: str | None = None
    official_local_start_date: str | None = None
    official_contest_id: str | None = None
    official_contest_url: str | None = None
    official_source: str | None = None
    cfp_schedule_source: str | None = None

    @property
    def key(self) -> tuple[int, str]:
        return (self.season, self.provider_id)

    def payload(self) -> dict[str, object]:
        return {
            "provider_id": self.provider_id,
            "season": self.season,
            "snapshot_date": self.snapshot_date,
            "home_team": self.home_team,
            "away_team": self.away_team,
            "notes": self.notes,
            "provider_week": self.provider_week,
            "original_canonical_week": self.original_canonical_week,
            "canonical_week": self.canonical_week,
            "source_snapshot_checksum": self.source_snapshot_checksum,
            "phase": self.phase,
            "phase_source": self.phase_source,
            "provider_phase": self.provider_phase,
            "official_local_start_date": self.official_local_start_date,
            "official_contest_id": self.official_contest_id,
            "official_contest_url": self.official_contest_url,
            "official_source": self.official_source,
            "cfp_schedule_source": self.cfp_schedule_source,
        }


@dataclass(frozen=True)
class PostseasonCorrectionRegistry:
    """Validated registry value; only the pinned instance is production trust."""

    version: str
    entries: tuple[PostseasonCorrection, ...]
    official_sources: Mapping[str, str]
    snapshot_checksums: Mapping[int, str]
    source_evidence_sha256: str | None = None
    checksum: str | None = None

    def payload(self, *, include_checksum: bool = True) -> dict[str, object]:
        value: dict[str, object] = {
            "version": self.version,
            "policy_id": REGISTRY_POLICY_ID,
            "official_sources": dict(sorted(self.official_sources.items())),
            "snapshot_checksums": {str(k): v for k, v in sorted(self.snapshot_checksums.items())},
            "source_evidence_sha256": self.source_evidence_sha256,
            "entries": [entry.payload() for entry in self.entries],
        }
        if include_checksum:
            value["checksum"] = self.computed_checksum
        return value

    @property
    def computed_checksum(self) -> str:
        encoded = json.dumps(self.payload(include_checksum=False), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
        return hashlib.sha256(encoded).hexdigest()

    def validate(self, *, require_pinned: bool = False) -> "PostseasonCorrectionRegistry":
        if self.version != REGISTRY_VERSION:
            raise ValueError("unsupported postseason correction registry version")
        if not self.entries:
            raise ValueError("postseason correction registry is empty")
        if self.checksum is not None and self.checksum != self.computed_checksum:
            raise ValueError("postseason correction registry checksum mismatch")
        seen: set[tuple[int, str]] = set()
        for entry in self.entries:
            if entry.key in seen:
                raise ValueError("postseason correction registry has duplicate game identity")
            seen.add(entry.key)
            _validate_entry(entry)
            expected = canonical_postseason_week(entry.season, entry.snapshot_date)
            if entry.canonical_week != expected:
                raise ValueError("postseason correction canonical week is not calendar-derived")
            if entry.source_snapshot_checksum != self.snapshot_checksums.get(entry.season):
                raise ValueError("postseason correction source snapshot binding mismatch")
        if require_pinned:
            assert_pinned_registry(self)
        return self

    def lookup(self, season: int, provider_id: str) -> PostseasonCorrection | None:
        key = (int(season), str(provider_id))
        return next((entry for entry in self.entries if entry.key == key), None)

    @property
    def provenance(self) -> dict[str, object]:
        return {
            "version": self.version,
            "policy_id": REGISTRY_POLICY_ID,
            "checksum": self.computed_checksum,
            "entry_count": len(self.entries),
            "official_sources": dict(sorted(self.official_sources.items())),
            "snapshot_checksums": {str(k): v for k, v in sorted(self.snapshot_checksums.items())},
            "source_evidence_sha256": self.source_evidence_sha256,
        }

    @classmethod
    def from_payload(cls, payload: Mapping[str, Any]) -> "PostseasonCorrectionRegistry":
        if not isinstance(payload, Mapping):
            raise ValueError("postseason correction registry payload is invalid")
        raw_entries = payload.get("entries")
        if not isinstance(raw_entries, list):
            raise ValueError("postseason correction registry entries are invalid")
        entries = tuple(_entry_from_payload(item) for item in raw_entries)
        raw_checksums = payload.get("snapshot_checksums") or {}
        if not isinstance(raw_checksums, Mapping):
            raise ValueError("postseason correction snapshot bindings are invalid")
        registry = cls(
            version=str(payload.get("version", "")),
            entries=entries,
            official_sources={str(k): str(v) for k, v in (payload.get("official_sources") or {}).items()},
            snapshot_checksums={int(k): str(v) for k, v in raw_checksums.items()},
            source_evidence_sha256=(str(payload["source_evidence_sha256"]) if payload.get("source_evidence_sha256") is not None else None),
            checksum=(str(payload["checksum"]) if payload.get("checksum") is not None else None),
        )
        registry.validate()
        return registry


def _entry_from_payload(value: Mapping[str, Any]) -> PostseasonCorrection:
    if not isinstance(value, Mapping):
        raise ValueError("postseason correction entry is invalid")
    required = ("provider_id", "season", "snapshot_date", "home_team", "away_team", "provider_week", "original_canonical_week", "canonical_week", "source_snapshot_checksum")
    if any(key not in value for key in required):
        raise ValueError("postseason correction entry is incomplete")
    return PostseasonCorrection(
        provider_id=str(value["provider_id"]),
        season=int(value["season"]),
        snapshot_date=str(value["snapshot_date"]),
        home_team=str(value["home_team"]),
        away_team=str(value["away_team"]),
        notes=(str(value["notes"]) if value.get("notes") is not None else None),
        provider_week=int(value["provider_week"]),
        original_canonical_week=int(value["original_canonical_week"]),
        canonical_week=int(value["canonical_week"]),
        source_snapshot_checksum=str(value["source_snapshot_checksum"]),
        phase=str(value.get("phase", "postseason")),
        phase_source=str(value.get("phase_source", "recovery_registry")),
        provider_phase=(str(value["provider_phase"]) if value.get("provider_phase") is not None else None),
        official_local_start_date=(str(value["official_local_start_date"]) if value.get("official_local_start_date") is not None else None),
        official_contest_id=(str(value["official_contest_id"]) if value.get("official_contest_id") is not None else None),
        official_contest_url=(str(value["official_contest_url"]) if value.get("official_contest_url") is not None else None),
        official_source=(str(value["official_source"]) if value.get("official_source") is not None else None),
        cfp_schedule_source=(str(value["cfp_schedule_source"]) if value.get("cfp_schedule_source") is not None else None),
    )

def _validate_entry(entry: PostseasonCorrection) -> None:
    if not re.fullmatch(r"\d+", entry.provider_id) or not entry.provider_id:
        raise ValueError("postseason correction provider_id is invalid")
    if entry.phase != "postseason" or entry.phase_source != "recovery_registry":
        raise ValueError("postseason correction phase provenance is invalid")
    if entry.provider_phase is not None:
        raise ValueError("postseason correction provider phase must remain absent")
    if entry.provider_week != 1 or entry.original_canonical_week != 1:
        raise ValueError("postseason correction original provider binding is invalid")
    if not entry.home_team.strip() or not entry.away_team.strip():
        raise ValueError("postseason correction team identity is invalid")
    try:
        parsed = datetime.fromisoformat(entry.snapshot_date.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError("postseason correction snapshot_date is invalid") from exc
    if parsed.tzinfo is None:
        raise ValueError("postseason correction snapshot_date must be timezone-aware")
    if entry.official_local_start_date is not None:
        try:
            month, day, year = (int(part) for part in entry.official_local_start_date.split("/"))
            if date(year, month, day).isoformat() != parsed.astimezone(ZoneInfo("America/New_York")).date().isoformat():
                raise ValueError("postseason correction official local date mismatch")
        except (ValueError, TypeError) as exc:
            if str(exc) == "postseason correction official local date mismatch":
                raise
            raise ValueError("postseason correction official local date is invalid") from exc
    if not re.fullmatch(r"[0-9a-f]{64}", entry.source_snapshot_checksum):
        raise ValueError("postseason correction source checksum is invalid")

def assert_pinned_registry(registry: PostseasonCorrectionRegistry) -> None:
    if registry.computed_checksum != PINNED_REGISTRY.computed_checksum:
        raise ValueError("postseason correction registry is not code-pinned")
    if registry.payload(include_checksum=False) != PINNED_REGISTRY.payload(include_checksum=False):
        raise ValueError("postseason correction registry differs from code-pinned entries")

