def _build_pinned() -> PostseasonCorrectionRegistry:
    entries = tuple(_entry_from_payload(row) for row in _RAW_ROWS)
    registry = PostseasonCorrectionRegistry(
        version=REGISTRY_VERSION,
        entries=entries,
        official_sources=PINNED_OFFICIAL_SOURCES,
        snapshot_checksums=PINNED_SNAPSHOT_CHECKSUMS,
        source_evidence_sha256=PINNED_SOURCE_EVIDENCE_SHA256,
    )
    registry.validate()
    return registry


PINNED_REGISTRY: Final[PostseasonCorrectionRegistry] = _build_pinned()
PINNED_REGISTRY_CHECKSUM: Final[str] = PINNED_REGISTRY.computed_checksum


def trusted_registry(registry: PostseasonCorrectionRegistry | None = None) -> PostseasonCorrectionRegistry:
    """Return the code-owned registry, rejecting arbitrary caller payloads."""

    if registry is None:
        return PINNED_REGISTRY
    registry.validate()
    assert_pinned_registry(registry)
    return PINNED_REGISTRY


def validate_recovery_classification(
    season: int,
    games: Sequence[object],
    provenance: Mapping[str, object] | None = None,
) -> None:
    """Reject known legacy postseason rows when they are left unclassified.

    This check runs for legacy schema-3 reads as well as schema-4 snapshots.
    Canonical fixtures without provider identity remain compatible because
    there is no provider Week 1/date tuple to classify.  Once a known late
    provider Week 1 row is present, it must either carry provider postseason
    metadata or the complete pinned recovery classification.
    """

    try:
        from .week_calendar import POSTSEASON_WINDOWS, _provider_datetime
    except ImportError:  # pragma: no cover - direct execution compatibility
        from week_calendar import POSTSEASON_WINDOWS, _provider_datetime

    expected = tuple(entry for entry in PINNED_REGISTRY.entries if entry.season == int(season))
    recovered = []
    for game in games:
        provider_id = str(getattr(game, "provider_id", "") or "")
        entry = PINNED_REGISTRY.lookup(season, provider_id) if provider_id else None
        phase = getattr(game, "phase", None)
        phase_source = getattr(game, "phase_source", None)
        if entry is not None:
            if phase_source == "recovery_registry":
                recovered.append(game)
            elif phase is None and phase_source is None:
                raise ValueError(
                    "known postseason provider Week 1 game requires recovery migration"
                )
        raw_week = getattr(game, "provider_week", None)
        raw_date = getattr(game, "date", None)
        if raw_week == 1 and raw_date is not None and int(season) in POSTSEASON_WINDOWS:
            local_day = _provider_datetime(raw_date).date()
            if local_day >= POSTSEASON_WINDOWS[int(season)].start_date:
                # Fresh provider-backed postseason games are authoritative
                # when the adapter supplied an explicit phase.  The pinned
                # registry is only for legacy recovery rows; requiring its
                # membership first would reject legitimate future-season
                # provider IDs before persistence and release validation.
                if phase_source == "provider" and phase == "postseason":
                    continue
                if entry is None:
                    raise ValueError(
                        "late provider Week 1 game is absent from the pinned postseason registry"
                    )
                if phase_source not in {"provider", "recovery_registry"} or phase != "postseason":
                    raise ValueError(
                        "late provider Week 1 game is not classified as postseason"
                    )
    if recovered or (provenance is not None and expected):
        validate_recovered_games(season, games, provenance)


def validate_recovered_games(
    season: int,
    games: Sequence[object],
    provenance: Mapping[str, object] | None,
) -> None:
    """Validate recovery phases against the code-owned identity registry.

    The registry provenance is evidence, not authority.  Its complete value
    must equal the code-pinned value, and every corrected game must bind to one
    pinned row.  This also requires all known rows for a migrated season so a
    partial correction cannot silently leave provider Week 1 postseason games
    in the regular-week bucket.
    """

    recovered = [
        game for game in games
        if getattr(game, "phase_source", None) == "recovery_registry"
    ]
    registry = PINNED_REGISTRY
    if not isinstance(provenance, Mapping):
        raise ValueError("postseason recovery phases require pinned registry provenance")
    if dict(provenance) != registry.provenance:
        raise ValueError("postseason recovery registry provenance is not code-pinned")
    expected = tuple(entry for entry in registry.entries if entry.season == int(season))
    if len(recovered) != len(expected):
        raise ValueError("postseason recovery snapshot is missing registry rows")
    seen: set[tuple[int, str]] = set()
    for game in recovered:
        provider_id = str(getattr(game, "provider_id", ""))
        entry = registry.lookup(season, provider_id)
        if entry is None:
            raise ValueError("postseason recovery game is absent from pinned registry")
        identity = (
            int(season),
            provider_id,
            str(getattr(game, "date", "")),
            str(getattr(game, "home_team", "")),
            str(getattr(game, "away_team", "")),
            getattr(game, "notes", None),
            getattr(game, "provider_week", None),
            getattr(game, "week", None),
        )
        expected_identity = (
            entry.season,
            entry.provider_id,
            entry.snapshot_date,
            entry.home_team,
            entry.away_team,
            entry.notes,
            entry.provider_week,
            entry.canonical_week,
        )
        if identity != expected_identity:
            raise ValueError("postseason recovery game identity differs from pinned registry")
        if entry.key in seen:
            raise ValueError("postseason recovery snapshot has duplicate registry rows")
        seen.add(entry.key)
    if seen != {entry.key for entry in expected}:
        raise ValueError("postseason recovery snapshot does not cover pinned registry")
